#include <iostream>
#include <cstdio>
#include <cstring>
using namespace std;

const int MAXN = 250010;
long long factorial[MAXN], invFactorial[MAXN];
long long dpTable[30][MAXN];
int bitsArray[MAXN];
long long totalN, maxM, modM;

long long nCr(int a, int b) {
    return factorial[a] * invFactorial[a - b] % modM * invFactorial[b] % modM;
}

void addMod(long long &x, long long y) {
    x += y;
    if (x >= modM) x -= modM;
}

int main() {
    cin >> totalN >> maxM >> modM;
    factorial[0] = invFactorial[0] = 1;
    factorial[1] = invFactorial[1] = 1;
    for (int i = 2; i <= totalN; i++) {
        int q = modM / i;
        int r = modM - i * q;
        factorial[i] = factorial[i - 1] * i % modM;
        invFactorial[i] = modM - (long long)q * invFactorial[r] % modM;
    }
    for (int i = 2; i <= totalN; i++) {
        invFactorial[i] = invFactorial[i - 1] * invFactorial[i] % modM;
    }
    long long answer = 1;
    for (int i = 1; i <= totalN; i++) answer = answer * maxM % modM;
    for (int i = 1; i <= totalN; i++) bitsArray[i] = bitsArray[i >> 1] + (i & 1);
    if (totalN % 2 == 1) {
        cout << answer << endl;
        return 0;
    }
    dpTable[0][0] = 1;
    int maxBitsCount = min(bitsArray[totalN], maxM);
    for (int i = 0; i < maxBitsCount; i++) {
        for (int j = 0; j < totalN; j++) {
            if (dpTable[i][j] == 0) continue;
            int mask = totalN ^ j;
            for (int k = mask, r; k > j; k = (k - 1) & mask) {
                r = k | j;
                addMod(dpTable[i + 1][r], dpTable[i][j] * invFactorial[k]);
            }
        }
    }
    for (int i = 1; i <= maxM; i++) {
        answer -= dpTable[i][totalN] * factorial[maxM] % modM * invFactorial[maxM - i] % modM * factorial[totalN] % modM;
    }
    answer = (modM + answer % modM) % modM;
    cout << answer << endl;
    return 0;
}
